    &lt;ModuleId&gt;506&lt;/ModuleId&gt;
    &lt;DataSource&gt;{&quot;DefinitionId&quot;:&quot;SqlQuery&quot;,&quot;Parameters&quot;:{&quot;DbConnector&quot;:{&quot;Type&quot;:&quot;Database&quot;,&quot;Group&quot;:&quot;&quot;,&quot;EntireGroup&quot;:false},&quot;ConnectionString&quot;:&quot;&quot;,&quot;QueryTimeout&quot;:&quot;&quot;,&quot;SqlQuery&quot;:&quot;SELECT\n    rt.Id AS ReviewTaskId,\n    fr.Id AS FundingRequestId,\n    fr.RequestNumber,\n    fr.Title,\n    o.Name AS Organization,\n    fr.RequestedAmount,\n    p.Name AS Priority,\n    rt.TaskType,\n    rt.AssignedDate,\n    rt.DueDate,\n    rt.Status AS TaskStatus,\n    s.Name AS RequestStatus\nFROM app.ReviewTask rt\nINNER JOIN app.FundingRequest fr\n    ON fr.Id = rt.FundingRequest\nLEFT JOIN app.Organization o\n    ON o.Id = fr.Organization\nLEFT JOIN app.FundingRequestPriority p\n    ON p.Id = fr.Priority\nLEFT JOIN app.FundingRequestStatus s\n    ON s.Id = fr.Status\nWHERE (rt.AssignedTo = @CurrentUserId OR @IsAdmin = &#39;true&#39;)\n  AND rt.Status IN (&#39;Pending&#39;, &#39;In Progress&#39;)\nORDER BY\n    CASE WHEN p.Id = 4 THEN 1\n         WHEN p.Id = 3 THEN 2\n         WHEN p.Id = 2 THEN 3\n         ELSE 4 END,\n    rt.AssignedDate ASC;&quot;,&quot;BindTokens&quot;:[{&quot;value&quot;:&quot;[User:UserId]&quot;,&quot;name&quot;:&quot;CurrentUserId&quot;},{&quot;value&quot;:&quot;[HasRole:Administrators]&quot;,&quot;name&quot;:&quot;IsAdmin&quot;}],&quot;IdColumn&quot;:&quot;ReviewTaskId&quot;,&quot;SqlQueryColumns&quot;:&quot;&quot;,&quot;SqlQueryInsert&quot;:&quot;&quot;,&quot;SqlQueryUpdate&quot;:&quot;&quot;,&quot;SqlQueryDelete&quot;:&quot;&quot;,&quot;OrderBy&quot;:&quot;&quot;,&quot;AddUrl&quot;:&quot;&quot;,&quot;EditUrl&quot;:&quot;&quot;,&quot;ViewUrl&quot;:&quot;&quot;},&quot;Fields&quot;:[{&quot;Title&quot;:&quot;ReviewTaskId&quot;,&quot;Name&quot;:&quot;ReviewTaskId&quot;,&quot;TypeStr&quot;:&quot;System.Int32, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;: